"""本地业务页面交互。

仅向演练页面增量输出元素与脚本：不改动既有元素 id、文案与脚本语义，
新增的材料要求提示、校验失败焦点跳转都可被浏览器演练直接观察。
"""

def detail_fragment(item):
    return "<select id=\"category\"><option>手作</option><option>食饮</option></select><input id=\"attachment\" type=\"file\"><output id=\"material-requirement\"></output><button id=\"draft\">保存演练草稿</button><output id=\"draft-state\"></output><button id=\"confirm\">查看确认页</button><output id=\"confirmation\"></output><output id=\"validation-error\"></output><script>let category=document.querySelector('#category'),attachment=document.querySelector('#attachment'),status=document.querySelector('#draft-state'),confirm=document.querySelector('#confirmation'),requirement=document.querySelector('#material-requirement');const requiredMaterials={'手作':'工艺说明文档（含传承人介绍）','食饮':'现场制作品安全说明'};const renderRequirement=()=>{requirement.textContent='所需材料：'+(requiredMaterials[category.value]||'按当前类别补充材料');};const draftKey='stall-draft:'+document.querySelector('main').dataset.key;let version=0;const restored=JSON.parse(sessionStorage.getItem(draftKey)||'null');if(restored){category.value=restored.category;status.textContent='草稿已恢复；材料需重新附上并核对';version=restored.version;}renderRequirement();category.addEventListener('change',renderRequirement);category.onchange=()=>{version++;attachment.value='';status.textContent='材料待核对';confirm.textContent=''};attachment.onchange=()=>{version++;status.textContent=attachment.files.length?'已预览：'+attachment.files[0].name:'材料待核对';confirm.textContent=''};document.querySelector('#draft').onclick=()=>{sessionStorage.setItem(draftKey,JSON.stringify({category:category.value,filename:attachment.files[0]?.name||null,version}));status.textContent='草稿：'+category.value+' / v'+version};document.querySelector('#confirm').onclick=()=>{let draft=JSON.parse(sessionStorage.getItem(draftKey)||'null');confirm.textContent=draft?.version===version?'待人工确认 / v'+version:'草稿已变化'};</script>"

def source_extension(item):
    return """<output id="upload-digest"></output><output id="draft-check"></output><script>(()=>{
let digest=document.querySelector('#upload-digest'),attachment=document.querySelector('#attachment'),check=document.querySelector('#draft-check'),category=document.querySelector('#category'),validationError=document.querySelector('#validation-error');const draftKey='stall-draft:'+document.querySelector('main').dataset.key;
const guardMaterial=()=>{if(!digest.textContent){validationError.textContent='校验未通过：当前类别缺少已核对材料，焦点已移回材料上传框';attachment.focus();return true;}validationError.textContent='';return false;};
attachment.addEventListener('change',async()=>{let file=attachment.files[0];validationError.textContent='';if(!file){digest.textContent='';return}let bytes=await file.arrayBuffer(),hash=await crypto.subtle.digest('SHA-256',bytes);digest.textContent='附件摘要：'+Array.from(new Uint8Array(hash)).map(value=>value.toString(16).padStart(2,'0')).join('');check.textContent='';});
category.addEventListener('change',()=>{digest.textContent='';check.textContent='';validationError.textContent='';});
document.querySelector('#draft').addEventListener('click',()=>{let stored=JSON.parse(sessionStorage.getItem(draftKey)||'null');if(stored){stored.digest=digest.textContent;sessionStorage.setItem(draftKey,JSON.stringify(stored));check.textContent=stored.category+' / '+stored.filename+' / '+stored.digest;}});
document.querySelector('#confirm').addEventListener('click',()=>{guardMaterial();let stored=JSON.parse(sessionStorage.getItem(draftKey)||'null');check.textContent=stored?.category===category.value && stored?.digest===digest.textContent?stored.category+'：材料摘要已核':'材料版本待核对';});
})();</script>"""
